#!/usr/bin/env python3
"""FM generated by the LR2021 itself: a PRAM blob (firmware/pram/pll.bin) writes the synthesizer
frequency word while the radio transmits a CW carrier. See docs/pram-pll.md.

  python3 tools/pll.py aprs --sdr                          # on-chip AFSK 1200 APRS frame, decoded by an RTL-SDR
  python3 tools/pll.py fsk --dev 5000 --us 1000 --n 400    # +-5 kHz square wave, 1 ms per symbol
  python3 tools/pll.py tone --khz 1 --dev 3000 --ms 300    # sine FM from a table
  python3 tools/pll.py sweep --span 200 --ms 300           # linear sweep over 200 kHz

Every mode transmits (default 908 MHz, -9 dBm, the console's PA settings). Use a frequency, power
and mode you are allowed to use, into a dummy load on the bench. The APRS frame uses the N0CALL
placeholder and the experimental APZ tocall: put your own callsign in before sending it on air.
--sdr records with rtl_sdr tuned 50 kHz below the carrier and decodes (aprs) or reports the
received tones.
"""
import argparse
import os
import struct
import subprocess
import sys
import tempfile
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
sys.path.insert(0, os.path.join(HERE, 'bench'))
import pram  # noqa: E402
import aprs  # noqa: E402
from radio_ports import default_port  # noqa: E402

BLOB = os.path.join(HERE, '..', 'firmware', 'pram', 'pll.bin')
TAB = 0x807800                       # free RAM (docs/lr2021-cpu.md#memory), 2 KB
CLK = 32.0e6                         # CPU clock in TX [HW]
OVH_SQUARE, OVH_TABLE, OVH_AFSK = 32, 34.5, 25   # loop cycles per update on top of the delay [HW]
AFSK_RATE, AFSK_SPB = 38400, 32      # audio updates per second, per bit
SDR_FS, SDR_OFF = 240e3, 50e3


def word(hz):
    """Synthesizer frequency word: Hz * 2^20 / 1e6."""
    return int(round(hz * 1048576 / 1e6))


def be32(v):
    return struct.pack('>I', v & 0xFFFFFFFF)


def ok(c, op, params=b'', nread=0, timeout=5.0):
    st, d = c.rc(op, nread, params, timeout)
    if st != 0:
        raise RuntimeError(f'rc {op:04X} {params.hex()} st={st}')
    return d


def mw(c, a, v):
    out = c.cmd(f'mw {a:X} {v:X}', 'mw st')
    if 'mw st=0' not in out:
        raise RuntimeError(out)


def write_table(c, data):
    data = bytes(data) + bytes(-len(data) % 4)
    if len(data) > 2048:
        raise ValueError('table is limited to 2 KB')
    for i in range(0, len(data), 4):
        mw(c, TAB + i, struct.unpack('<I', data[i:i + 4])[0])


def setup(port, mhz, dbm):
    c = pram.Console(port)
    if 'OK' not in c.cmd(f'set radio {mhz},62.5,7,5', '->', 10):
        raise RuntimeError('set radio failed')
    c.cmd(f'set tx {dbm}', '->')
    c.cmd('hold on', 'hold st')
    pram.load(c, BLOB)
    if c.rc(0x012D, 4, b'\x02')[1] != b'PLL1':
        raise RuntimeError('blob did not answer')
    return c


def carrier_on(c, mhz):
    ok(c, 0x0128, b'\0')                       # standby
    ok(c, 0x0200, be32(int(round(mhz * 1e6))))
    ok(c, 0x020E, b'\x02')                     # SetTxTestMode: continuous wave


def carrier_off(c):
    ok(c, 0x0128, b'\0')


def pll(c, n, cyc, mode, step, tlen=0):
    return ok(c, 0x012D, b'\x01' + struct.pack('>HIBiH', n, max(0, int(round(cyc))), mode, step, tlen), 4)


def afsk(c, nbits, dev):
    inc = lambda f: int(round(f / AFSK_RATE * 2 ** 32)) & 0xFFFFFFFF
    p = struct.pack('>HIHiII', nbits, int(round(CLK / AFSK_RATE - OVH_AFSK)), AFSK_SPB,
                    int(round(word(dev) / 127)), inc(1200), inc(2200))
    return ok(c, 0x012D, b'\x03' + p, 4)


class Sdr:
    def __init__(self, mhz, seconds):
        self.path = tempfile.mktemp(suffix='.u8')
        self.p = subprocess.Popen(['rtl_sdr', '-f', str(int(mhz * 1e6 - SDR_OFF)), '-s', str(int(SDR_FS)), '-g', '40',
                                   '-n', str(int(SDR_FS * seconds)), self.path],
                                  stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        time.sleep(0.6)                         # tuner start-up

    def iq(self):
        self.p.wait()
        z = aprs.load_rtl(self.path, SDR_FS, SDR_OFF)
        os.unlink(self.path)
        return z


def report_tones(z):
    """Histogram of the received frequency (1 ms FFT peaks) while the carrier is on."""
    n = int(SDR_FS / 1000)
    f = np.fft.fftshift(np.fft.fftfreq(n, 1 / SDR_FS))
    peaks = []
    for i in range(len(z) // n):
        s = np.abs(np.fft.fftshift(np.fft.fft(z[i * n:(i + 1) * n] * np.hanning(n)))) ** 2
        if s.max() > 30 * np.median(s):
            peaks.append(f[np.argmax(s)])
    if not peaks:
        print('no carrier seen')
        return
    v, cnt = np.unique(np.round(np.array(peaks) / 1e3), return_counts=True)
    top = sorted(zip(cnt, v), reverse=True)[:6]
    print('received (kHz from carrier: ms):', ', '.join(f'{k:+.0f}: {m}' for m, k in top),
          '(1 kHz bins; the RTL-SDR has its own offset)')


def run(args, body, seconds):
    c = setup(args.port, args.mhz, args.dbm)
    pre = getattr(args, 'prepare', None)
    if pre:
        pre(c)
    sdr = Sdr(args.mhz, seconds + 1.0) if args.sdr else None
    carrier_on(c, args.mhz)
    try:
        t = time.time()
        body(c)
        print(f'command took {time.time() - t:.2f} s')
    finally:
        carrier_off(c)
    return sdr.iq() if sdr else None


def cmd_aprs(args):
    tb = aprs.tones(aprs.frame(args.src, args.dest, args.info), preamble_flags=args.flags)
    secs = len(tb) / 1200
    print(f'{args.src}>{args.dest}:{args.info}  {len(tb)} tone bits, {secs:.2f} s')
    if secs > 0.9:
        raise SystemExit('frame too long for one command (~1 s BUSY limit)')
    by = bytearray((len(tb) + 7) // 8)
    for j, b in enumerate(tb):
        if b:
            by[j >> 3] |= 1 << (j & 7)
    args.prepare = lambda c: write_table(c, by)
    z = run(args, lambda c: afsk(c, len(tb), args.dev), secs)
    if z is not None:
        res = aprs.decode_iq(z, SDR_FS, 1)
        print(f'{len(res)} frame(s) decoded with valid CRC')
        for r in res:
            print('  ', r)


def cmd_fsk(args):
    cyc = CLK * args.us / 1e6 - OVH_SQUARE
    z = run(args, lambda c: pll(c, args.n, cyc, 0, word(args.dev)), args.n * args.us / 1e6)
    if z is not None:
        report_tones(z)


def cmd_tone(args):
    L = 64 if args.khz <= 10 else 16 if args.khz <= 50 else 4
    tab = np.round(127 * np.sin(2 * np.pi * np.arange(L) / L)).astype(int)
    cyc = CLK / (args.khz * 1e3 * L) - OVH_TABLE
    n = min(65535, int(args.ms / 1e3 * args.khz * 1e3 * L))
    args.prepare = lambda c: write_table(c, bytes(int(v) & 0xFF for v in tab))
    z = run(args, lambda c: pll(c, n, cyc, 1, int(round(word(args.dev) / 127)), L), args.ms / 1e3)
    if z is not None:
        a = aprs.fm_audio(z, SDR_FS, 1, args.dev + 2 * args.khz * 1e3 + 5e3)
        amp = np.abs(z[1:])
        a = a[amp > 0.4 * np.percentile(amp, 97)]
        S = np.abs(np.fft.rfft(a * np.hanning(len(a))))
        fr = np.fft.rfftfreq(len(a), 1 / SDR_FS)
        k = np.argmax(S * (fr > 200))
        print(f'demodulated tone {fr[k] / 1e3:.3f} kHz')


def cmd_sweep(args):
    n = 4096
    step = word(args.span * 1e3 / n)
    cyc = CLK * args.ms / 1e3 / n - OVH_SQUARE
    z = run(args, lambda c: pll(c, n, cyc, 2, max(1, step)), args.ms / 1e3)
    if z is not None:
        report_tones(z)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--board', choices=['xiao', 'nicerf'], default='xiao')
    ap.add_argument('--mhz', type=float, default=908.0)
    ap.add_argument('--dbm', type=int, default=-9)
    ap.add_argument('--sdr', action='store_true', help='record with rtl_sdr and analyse')
    sub = ap.add_subparsers(dest='cmd', required=True)
    a = sub.add_parser('aprs')
    a.add_argument('--src', default='N0CALL')
    a.add_argument('--dest', default='APZ001')
    a.add_argument('--info', default='>LR2021 PLL AFSK test')
    a.add_argument('--dev', type=float, default=3000, help='peak deviation, Hz')
    a.add_argument('--flags', type=int, default=30, help='preamble flags')
    f = sub.add_parser('fsk')
    f.add_argument('--dev', type=float, default=5000)
    f.add_argument('--us', type=float, default=1000, help='symbol length')
    f.add_argument('--n', type=int, default=400)
    t = sub.add_parser('tone')
    t.add_argument('--khz', type=float, default=1.0)
    t.add_argument('--dev', type=float, default=3000)
    t.add_argument('--ms', type=float, default=300)
    s = sub.add_parser('sweep')
    s.add_argument('--span', type=float, default=200, help='kHz, centred on the carrier')
    s.add_argument('--ms', type=float, default=300)
    args = ap.parse_args()
    args.port = default_port('XIAO', '/dev/ttyACM0') if args.board == 'xiao' else default_port('RAK3401', '/dev/ttyACM1')
    {'aprs': cmd_aprs, 'fsk': cmd_fsk, 'tone': cmd_tone, 'sweep': cmd_sweep}[args.cmd](args)


if __name__ == '__main__':
    main()
